"""Inputs for the `fn/ShapeDispatch` unit.

The world block at arena +0x8000 holds the five array pointers at
+0x2d0/+0x2e8/+0x300/+0x318/+0x330 and one shape record per type. The input
record at +0x7000 selects the type and index; the matrix is at
+0x7200. Cases cover types 0, 1, 2 and 4; type 3 is open.
"""

from __future__ import annotations

import random
import struct
from typing import List

from emu_oracle import ArgSpec

WORLD_OFF = 0x8000
RECORD_OFF = 0x7000
MATRIX_OFF = 0x7200
WORLD_BASE = 0x200008000
CASES = [(0, ''), (1, ''), (2, ''), (4, '')]


def _fbits(value: float) -> int:
    return struct.unpack("<I", struct.pack("<f", value))[0]


def _record(kind: int) -> bytes:
    rec = bytearray(random.Random(0x5348_4150 ^ kind).getrandbits(8) for _ in range(0x28))
    rec[0x20] = kind
    struct.pack_into("<i", rec, 0x24, 0)
    return bytes(rec)


def make_args(i: int) -> List[ArgSpec]:
    kind, world_hex = CASES[i % len(CASES)]
    rng = random.Random(0x4D41_5452 ^ kind)
    m = [rng.uniform(-2.0, 2.0) for _ in range(16)]
    return [
        ArgSpec(kind="ptr", mem=_record(kind), arena_offset=RECORD_OFF),
        ArgSpec(kind="ptr", mem=bytes.fromhex(world_hex), arena_offset=WORLD_OFF),
        ArgSpec(
            kind="ptr",
            mem=b"".join(struct.pack("<I", _fbits(v)) for v in m),
            arena_offset=MATRIX_OFF,
        ),
        ArgSpec(kind="u64", bits=WORLD_BASE),
    ]
